// Consumer defines exactly what it needs, not *os.File.
func Count(r io.Reader) (int, error) {
	buf := make([]byte, 32*1024)
	total := 0
	for {
		n, err := r.Read(buf)
		total += n
		if err == io.EOF {
			return total, nil
		}
		if err != nil {
			return total, err
		}
	}
}

