// Proxy: same interface, adds caching.
type Store interface{ Get(id string) ([]byte, error) }

type cachingProxy struct {
	real  Store
	cache map[string][]byte
}

func (p *cachingProxy) Get(id string) ([]byte, error) {
	if v, ok := p.cache[id]; ok {
		return v, nil
	}
	v, err := p.real.Get(id)
	if err == nil {
		p.cache[id] = v
	}
	return v, err
}

