type EventBus struct {
	mu   sync.RWMutex
	subs []chan string
}

func (b *EventBus) Subscribe() <-chan string {
	ch := make(chan string, 8) // buffered: bounded backpressure
	b.mu.Lock()
	b.subs = append(b.subs, ch)
	b.mu.Unlock()
	return ch
}

func (b *EventBus) Publish(ev string) {
	b.mu.RLock()
	defer b.mu.RUnlock()
	for _, ch := range b.subs {
		select {
		case ch <- ev: // non-blocking
		default: // drop if subscriber is slow — avoids stalling publisher
		}
	}
}

